import{decompress}from"./codec/deflate.js";import{b64decode}from"./codec/base64.js";import{minifyJS}from"./minify/js.js";const READER_URL=new URL("data:application/gzip;base64,",import.meta.url);const SERVER_URL=new URL("data:application/gzip;base64,",import.meta.url);const cache=new Map();async function bytesOf(url){const s=String(url);if(s.startsWith('data:'))return b64decode(s.slice(s.indexOf(',')+1));const r=await fetch(url);if(!r.ok)throw new Error('bundle '+r.status);return new Uint8Array(await r.arrayBuffer());}
function load(url,min){const k=String(url);if(!cache.has(k)){const p=(async()=>{const gz=await bytesOf(url);if(gz[0]!==0x1f||gz[1]!==0x8b)throw new Error('not a bundle');const text=new TextDecoder().decode(await decompress(gz,'gzip'));return min?minifyJS(text):text;})();p.catch(()=>cache.delete(k));cache.set(k,p);}
return cache.get(k);}
const readerCode=()=>load(READER_URL,true);const serverCode=()=>load(SERVER_URL,true);export{readerCode,serverCode};